<?php
declare(strict_types=1);session_start();require_once __DIR__.'/../config/database.php';
$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';
if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$_SESSION['auth_error']='Isi data dengan benar. Password minimal 8 karakter.';header('Location:/auth/register.php');exit;}
try{$pdo=db();$pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO users(name,email,password,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$stmt=$pdo->prepare('INSERT INTO businesses(name,owner_id,created_at,updated_at) VALUES(?,?,NOW(),NOW())');$stmt->execute([$name,$id]);$businessId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO business_user(business_id,user_id,role) VALUES(?,?,?)')->execute([$businessId,$id,'owner']);$pdo->commit();session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['user_name']=$name;$_SESSION['user_email']=$email;header('Location:/');exit;}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$code=(string)$e->getCode();$_SESSION['auth_error']=$code==='23000'?'Email sudah terdaftar. Gunakan email lain.':'Pendaftaran gagal: '.$e->getMessage();header('Location:/auth/register.php');exit;}
